import{f as o,o as t,c as d,a4 as a}from"./chunks/framework.6QvN0vQS.js";const P=JSON.parse('{"title":"Casos de prueba de aceptación — M12 CMP — Compras y proveedores","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/20-casos-prueba/M12-CMP-compras-proveedores.md","filePath":"entregables-analisis-diseno/20-casos-prueba/M12-CMP-compras-proveedores.md","lastUpdated":null}'),i={name:"entregables-analisis-diseno/20-casos-prueba/M12-CMP-compras-proveedores.md"};function r(n,e,c,s,l,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="casos-de-prueba-de-aceptacion-—-m12-cmp-—-compras-y-proveedores" tabindex="-1">Casos de prueba de aceptación — M12 CMP — Compras y proveedores <a class="header-anchor" href="#casos-de-prueba-de-aceptacion-—-m12-cmp-—-compras-y-proveedores" aria-label="Permalink to &quot;Casos de prueba de aceptación — M12 CMP — Compras y proveedores&quot;">​</a></h1><p>Parte de <a href="./../20-casos-prueba"><code>20-casos-prueba.md</code></a> (artefacto 9.2). Fuente: <a href="./../../especificacion/anexos/M12-CMP-compras-proveedores"><code>M12-CMP-compras-proveedores.md</code></a> (solo lectura). Generado por <code>_trabajo/gen_casos_prueba.py</code> y revisado; ante diferencias prevalece el anexo.</p><p>Resumen: 115 CP de requisitos funcionales, 25 CP de escenarios ESC y 9 CP de casos de uso CU.</p><p>Convenciones: el formato Dado / Cuando / Entonces sigue <code>07-estrategia-pruebas.md</code> §13; la ola de un CP de RF es la del prompt que lo implementa en <code>03</code> (prevalece sobre la columna del anexo); la de un CP de escenario es la última ola de los RF que cita o la que el escenario declara. Prioridad Extensión del anexo se agrupa como Estándar. Todos los datos son ficticios (TEN-001, TEN-002 y semillas del §18 del anexo).</p><h2 id="_1-casos-por-requisito-funcional" tabindex="-1">1. Casos por requisito funcional <a class="header-anchor" href="#_1-casos-por-requisito-funcional" aria-label="Permalink to &quot;1. Casos por requisito funcional&quot;">​</a></h2><p>Precondiciones comunes de esta sección: ola indicada desplegada en <code>staging</code> o <code>sandbox</code>; tenant ficticio TEN-001 con la configuración publicada y las semillas del M12 §18; usuario con la capability que exige el RF (el caso negativo sin capability lo cubre la suite de permisos negativos, <code>07</code> §4.3). Resultado esperado: el criterio de aceptación del RF se cumple, la prueba automatizada cita el RF y el CP en su nombre, y quedan auditoría y evento cuando hay cambio persistente.</p><h3 id="_1-1-proveedores-m12-§5-1" tabindex="-1">1.1 Proveedores (M12 §5.1) <a class="header-anchor" href="#_1-1-proveedores-m12-§5-1" aria-label="Permalink to &quot;1.1 Proveedores (M12 §5.1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0001</td><td>RF-CMP-001; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>ABM de proveedores: razón social, nombre de fantasía, CUIT, condición de IVA (<code>SITIVA</code>), inscripción IIBB y jurisdicciones, domicilio fiscal y comercial, teléfonos, emails, contacto, condición de pago por defecto, moneda, cuenta contable…</td><td>CUIT único por tenant; un proveedor bloqueado no recibe OC ni OP.</td></tr><tr><td>CP-CMP-0002</td><td>RF-CMP-002; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>integración</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Validar CUIT (dígito verificador) y consultar el padrón de ARCA mediante el componente de M06 al dar de alta o modificar (P218), proponiendo datos; alertar si el certificado/constancia del proveedor está vencido (P217) sin abrir páginas…</td><td>Con P218 activo, un CUIT inexistente en el padrón muestra advertencia y queda registrada la consulta.</td></tr><tr><td>CP-CMP-0003</td><td>RF-CMP-003; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>CBU/CVU del proveedor: varias cuentas con descripción, banco, titular y CUIT del titular; validación de formato; <strong>cambio o alta de CBU con aprobación T11</strong> y aviso al proveedor (prevención de fraude); cuenta preferida.</td><td>Una OP no usa un CBU con cambio pendiente de aprobación.</td></tr><tr><td>CP-CMP-0004</td><td>RF-CMP-004; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Mostrar y editar, desde la ficha del proveedor, los regímenes de retención aplicables, exclusiones y certificados de no retención con vigencia (los datos son de M06, <code>withholdingAssignments</code>); importar retenciones/alícuotas de proveedores…</td><td>La ficha muestra lo que M06 aplicará en la próxima OP.</td></tr><tr><td>CP-CMP-0005</td><td>RF-CMP-005; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Tipos de producto que provee cada proveedor, para filtrar invitaciones a cotizar.</td><td>Al invitar a cotizar un rubro se sugieren solo proveedores con ese tipo.</td></tr><tr><td>CP-CMP-0006</td><td>RF-CMP-006; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Personas autorizadas del proveedor: nombre, documento, fecha de autorización, caducidad opcional, observación; uso en la entrega de valores (M14).</td><td>Un autorizado caducado no puede retirar pagos.</td></tr><tr><td>CP-CMP-0007</td><td>RF-CMP-007; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Valoraciones del proveedor: usuario, fecha, cualidad, puntuación, observación; más indicadores automáticos (entregas a término, diferencias de cantidad y precio, devoluciones) para &quot;medir cumplimiento de proveedores&quot;.</td><td>El tablero del proveedor muestra puntaje promedio y % de entregas a término del período.</td></tr><tr><td>CP-CMP-0008</td><td>RF-CMP-008; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Rubros: &quot;Materiales eléctricos&quot; (pago diferido), &quot;Equipos de telecomunicaciones&quot;, &quot;Servicios&quot;</td><td>Rubros de proveedores unificados (un solo catálogo con banco y pago diferido) y asignación de uno o varios rubros con fecha.</td><td>Un rubro con &quot;pago diferido&quot; habilita pagos diferidos a sus proveedores (P2015/P2016 en M14).</td></tr><tr><td>CP-CMP-0009</td><td>RF-CMP-009; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Observaciones del proveedor y notas con fecha y usuario.</td><td>Las notas son inmutables; se agregan nuevas.</td></tr><tr><td>CP-CMP-0010</td><td>RF-CMP-010; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Vincular el proveedor con cuentas/personas de M01 (proveedor que también es socio o usuario), con tipo de relación.</td><td>La ficha 360 del socio muestra su rol de proveedor; no hay compensación automática de saldos.</td></tr><tr><td>CP-CMP-0011</td><td>RF-CMP-011; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>seguridad</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Proveedores que son empleados: ocultar sus facturas, recibos y datos en compras e informes salvo capability <code>cmp.proveedoresEmpleados.ver</code> (P2653, P2709).</td><td>Un comprador sin la capability no ve importes de proveedores-empleado.</td></tr><tr><td>CP-CMP-0012</td><td>RF-CMP-012; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Comunicaciones con el proveedor por email, SMS y WhatsApp (T09) con plantilla; circulares a proveedores (texto masivo por rubro o tipo) e historial de correspondencia.</td><td>Cada envío queda en <code>supplierCorrespondence</code> con estado de entrega.</td></tr><tr><td>CP-CMP-0013</td><td>RF-CMP-013; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Trámites y documentación del proveedor (constancias, seguros, habilitaciones) con vencimiento y adjuntos en el expediente T11; alerta de vencimiento.</td><td>Un documento obligatorio vencido bloquea nuevas OC si la política lo exige.</td></tr><tr><td>CP-CMP-0014</td><td>RF-CMP-014; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Consulta de situación crediticia del proveedor en la Central de Deudores del BCRA como enlace informativo.</td><td>Sin confirmación, solo enlace externo.</td></tr><tr><td>CP-CMP-0015</td><td>RF-CMP-015; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>seguridad</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Acceso al portal de proveedores por invitación individual con usuario propio (T02), reemplazando la contraseña genérica y el &quot;blanqueo&quot; manual.</td><td>No existe contraseña compartida entre proveedores.</td></tr><tr><td>CP-CMP-0016</td><td>RF-CMP-016; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Cuenta corriente del proveedor: comprobantes, pagos, anticipos, NC, saldo, vencidos y a vencer, con fecha de corte.</td><td>Saldo = Σ comprobantes − Σ aplicaciones de OP − NC aplicadas, a la fecha de corte.</td></tr><tr><td>CP-CMP-0017</td><td>RF-CMP-017; M12 §5.1; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Búsqueda y selección de proveedores por CUIT, código, nombre, rubro, tipo de producto y valoración (selector embebible en otros módulos y selección múltiple).</td><td>El selector respeta el alcance de datos.</td></tr><tr><td>CP-CMP-0018</td><td>RF-CMP-018; M12 §5.1; PRO-O3-03</td><td>O3</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Padrón mínimo de proveedores (razón social, CUIT, condición IVA) para registrar el ingreso de equipos serializados del piloto.</td><td>El ingreso de módems del piloto referencia un proveedor existente.</td></tr></tbody></table><h3 id="_1-2-catalogos-de-compras-m12-§5-2" tabindex="-1">1.2 Catálogos de compras (M12 §5.2) <a class="header-anchor" href="#_1-2-catalogos-de-compras-m12-§5-2" aria-label="Permalink to &quot;1.2 Catálogos de compras (M12 §5.2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0020</td><td>RF-CMP-020; M12 §5.2; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Conceptos: &quot;Flete&quot;, &quot;Mantenimiento&quot;, &quot;Servicios públicos&quot;, &quot;Anticipo a proveedores&quot;</td><td>Conceptos de compra (no inventariables): descripción, descripción para formulario, unidad, rubro contable, alícuota de IVA, no gravado, tipo, tipo de IVA, código IIBB; retenciones aplicables por concepto (en M06).</td><td>Un concepto sin rubro no se usa si el tenant exige imputación.</td></tr><tr><td>CP-CMP-0021</td><td>RF-CMP-021; M12 §5.2; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>Destinatarios de SA (áreas/personas receptoras).</td><td>Con P2705 la SA exige destinatario.</td></tr><tr><td>CP-CMP-0022</td><td>RF-CMP-022; M12 §5.2; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>Unidades de gasto y su panel al cargar productos desde un vale (P2906, uso en M13). El catálogo es <code>expenseUnits</code> de M13 (CTR-DAT-54); M12 lo consulta.</td><td>La unidad de gasto se imputa en la línea.</td></tr><tr><td>CP-CMP-0023</td><td>RF-CMP-023; M12 §5.2; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Tipos de combustible y registro de litros y km por comprobante de compra de combustible. El catálogo de tipos es <code>fuelTypes</code> de M18 (CTR-DAT-54); M12 registra litros y km en el comprobante.</td><td>El informe de consumo de combustible suma litros por vehículo/movimiento.</td></tr><tr><td>CP-CMP-0024</td><td>RF-CMP-024; M12 §5.2; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>Modalidades de contratación: sin asignar, caja chica, compulsa/mail, concurso de precios, concurso, licitación; cada una con umbrales y documentos exigidos configurables.</td><td>Una SA por encima del umbral de compulsa exige al menos N cotizaciones.</td></tr><tr><td>CP-CMP-0025</td><td>RF-CMP-025; M12 §5.2; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Conceptos: &quot;Flete&quot;, &quot;Mantenimiento&quot;, &quot;Servicios públicos&quot;, &quot;Anticipo a proveedores&quot;</td><td>Tipos de comprobante de compra y sus operaciones (suma/resta saldo, informa impuestos, mueve stock, anticipo, OP) desde el catálogo de tipos de comprobante de M05/T04.</td><td>Un tipo sin operación configurada no se ofrece.</td></tr><tr><td>CP-CMP-0026</td><td>RF-CMP-026; M12 §5.2; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Previsiones de pagos periódicos por proveedor, concepto o producto con periodicidad (mensual, bimestral, trimestral, semanal, quincenal), vigencia e importe, expuestas a la proyección de M14.</td><td>Una previsión mensual de ARS 10.000 de enero a marzo genera 3 vencimientos proyectados.</td></tr></tbody></table><h3 id="_1-3-solicitud-de-aprovisionamiento-m12-§5-3" tabindex="-1">1.3 Solicitud de aprovisionamiento (M12 §5.3) <a class="header-anchor" href="#_1-3-solicitud-de-aprovisionamiento-m12-§5-3" aria-label="Permalink to &quot;1.3 Solicitud de aprovisionamiento (M12 §5.3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0030</td><td>RF-CMP-030; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>Alta de SA con ítems de producto, concepto o texto libre: cantidad, unidad, costo estimado (con precio de última compra), solicitante, destinatario, criticidad (normal, alta, urgente), modalidad, fecha requerida, observaciones; y **por…</td><td>Una SA para &quot;reposición de módems del servicio INT&quot; guarda servicio y centro de costo en la línea.</td></tr><tr><td>CP-CMP-0031</td><td>RF-CMP-031; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Rubros: &quot;Materiales eléctricos&quot; (pago diferido), &quot;Equipos de telecomunicaciones&quot;, &quot;Servicios&quot;</td><td>Originar SA desde: punto de reposición de M13, OT/obra de M10 (materiales faltantes), fabricación (M13) o manualmente.</td><td>La SA conserva el vínculo con su origen.</td></tr><tr><td>CP-CMP-0032</td><td>RF-CMP-032; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Aprobación de SA por workflow T11 según política (monto estimado, área, criticidad), con opción de <strong>doble aprobación</strong> por usuarios distintos (P2867). Nunca se autoaprueba por procesar un ítem.</td><td>Procesar un ítem de una SA no aprobada devuelve error <code>cmp/request-not-approved</code>.</td></tr><tr><td>CP-CMP-0033</td><td>RF-CMP-033; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Visibilidad: quien no puede aprobar ve solo SA aprobadas para procesar; filtro de vigencia en días (P2036) que <strong>sí</strong> excluye SA más antiguas que la vigencia.</td><td>Con vigencia 30, una SA de hace 45 días no aparece en pendientes.</td></tr><tr><td>CP-CMP-0034</td><td>RF-CMP-034; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Estados: borrador, pendiente de aprobación, aprobada, rechazada, en proceso (compras la tomó), parcialmente procesada, procesada, descartada, anulada; reabrir (&quot;marcar pendiente&quot;) con motivo.</td><td>No se elimina una SA con ítems procesados; se anula.</td></tr><tr><td>CP-CMP-0035</td><td>RF-CMP-035; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Aprobación por informe impreso para firma del aprobador (marca &quot;exportada&quot;), como alternativa al workflow electrónico.</td><td>El PDF incluye monto estimado y precio de última compra.</td></tr><tr><td>CP-CMP-0036</td><td>RF-CMP-036; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>seguridad</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Aprobación masiva de SA filtradas por fecha y modalidad, con la misma capability e historial por documento.</td><td>Las SA para las que el usuario no tiene banda quedan rechazadas en el resultado con causa.</td></tr><tr><td>CP-CMP-0037</td><td>RF-CMP-037; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Mostrar disponibilidad comprometida del producto: saldo de OC abiertas, facturas pendientes de recepción y presupuestos aprobados con obra (M11), junto con el stock de M13.</td><td>Al pedir 10 módems se ve que hay 4 en OC abiertas.</td></tr><tr><td>CP-CMP-0038</td><td>RF-CMP-038; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: &quot;Flete&quot;, &quot;Mantenimiento&quot;, &quot;Servicios públicos&quot;, &quot;Anticipo a proveedores&quot;</td><td>Advertir si ya existe un pedido abierto del mismo producto o concepto (SA sin recibir u OC con saldo pendiente).</td><td>La búsqueda funciona igual para productos y conceptos.</td></tr><tr><td>CP-CMP-0039</td><td>RF-CMP-039; M12 §5.3; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Solicitar cotización de los materiales de una SA por mail con plantilla (P2888).</td><td>El mail llega con los ítems y el enlace al portal.</td></tr></tbody></table><h3 id="_1-4-cotizaciones-concursos-y-licitaciones-m12-§5-4" tabindex="-1">1.4 Cotizaciones, concursos y licitaciones (M12 §5.4) <a class="header-anchor" href="#_1-4-cotizaciones-concursos-y-licitaciones-m12-§5-4" aria-label="Permalink to &quot;1.4 Cotizaciones, concursos y licitaciones (M12 §5.4)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0040</td><td>RF-CMP-040; M12 §5.4; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Generar solicitudes de cotización a uno o varios proveedores desde SA aprobadas (una por proveedor, agrupadas), con vencimiento configurable (default 15 días), moneda y cotización.</td><td>Tres proveedores invitados generan tres cotizaciones del mismo grupo.</td></tr><tr><td>CP-CMP-0041</td><td>RF-CMP-041; M12 §5.4; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Cargar precios cotizados por el comprador o por el proveedor en el portal (precio, validez, plazo de entrega, observación), mostrando costo anterior e IVA calculado según la situación de IVA de la cooperativa (P527); marcar enviada o…</td><td>Una cotización cotizada exige costo ≠ 0 en todos sus ítems.</td></tr><tr><td>CP-CMP-0042</td><td>RF-CMP-042; M12 §5.4; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Cuadro comparativo de cotizaciones hermanas por ítem (precio, total en pesos P3119, plazo, valoración del proveedor) y últimas cotizaciones/órdenes del producto.</td><td>Si la SA se cotizó a un solo proveedor, se informa que no hay comparación.</td></tr><tr><td>CP-CMP-0043</td><td>RF-CMP-043; M12 §5.4; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Evaluar/adjudicar por ítem (contratado o descartado) con ajuste de cantidad y justificación cuando no se elige el menor precio.</td><td>Adjudicar un precio no mínimo exige justificación.</td></tr><tr><td>CP-CMP-0044</td><td>RF-CMP-044; M12 §5.4; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Concursos de precios, concursos y licitaciones: numeración correlativa por modalidad, invitación por plantilla (P2893), pliego y adjuntos, recepción de ofertas en sobre cerrado hasta la fecha de apertura, acta de apertura, planilla de…</td><td>Ninguna oferta es visible para compras antes de la apertura.</td></tr><tr><td>CP-CMP-0045</td><td>RF-CMP-045; M12 §5.4; PRO-O8-01</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Generar la OC desde los ítems adjudicados.</td><td>Un ítem adjudicado no genera dos OC.</td></tr></tbody></table><h3 id="_1-5-ordenes-de-compra-m12-§5-5" tabindex="-1">1.5 Órdenes de compra (M12 §5.5) <a class="header-anchor" href="#_1-5-ordenes-de-compra-m12-§5-5" aria-label="Permalink to &quot;1.5 Órdenes de compra (M12 §5.5)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0050</td><td>RF-CMP-050; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Alta de OC: proveedor, fecha, forma y condición de pago, plazo y lugar de entrega, fecha de entrega (obligatoria si P2735), fecha estimada de pago (obligatoria si P2810), solicitante (usuario si P2447), firmante, departamento, moneda…</td><td>Con P2335, una OC sin todos los campos obligatorios no se emite.</td></tr><tr><td>CP-CMP-0051</td><td>RF-CMP-051; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Cada línea de OC identifica servicio, destino (depósito/OT/obra con P3101), centro de costo y, si abastece varios servicios, una <strong>distribución explícita</strong> (porcentaje o cantidad) que suma 100 % sin duplicar el total.</td><td>Una OC de ARS 40.000 compartida 50/50 entre INT y TV informa ARS 20.000 por servicio y ARS 40.000 en total.</td></tr><tr><td>CP-CMP-0052</td><td>RF-CMP-052; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Aprobación de OC por bandas de monto y categoría en T11 (reemplaza P2377/P2382: &quot;autorizada por defecto&quot; o &quot;pendiente si supera monto&quot;), con capability y segregación; una OC no aprobada no se envía ni se recibe.</td><td>Con banda &quot;≥ ARS 500.000 requiere gerencia&quot;, una OC de ARS 600.000 queda <code>pendingApproval</code> hasta que gerencia apruebe.</td></tr><tr><td>CP-CMP-0053</td><td>RF-CMP-053; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Enviar la OC al proveedor por mail con plantilla (P2905) y publicarla en el portal; el proveedor confirma recepción y fecha comprometida.</td><td>La OC enviada registra fecha, canal y confirmación.</td></tr><tr><td>CP-CMP-0054</td><td>RF-CMP-054; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>OC abierta (marco) con precio y cantidad máximos por vigencia y <strong>liberaciones</strong> parciales (reemplaza la nota de pedido); consumo del saldo marco.</td><td>Una liberación que supera el saldo del marco se rechaza.</td></tr><tr><td>CP-CMP-0055</td><td>RF-CMP-055; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Modificar una OC aprobada crea una nueva versión que vuelve a aprobación si cambia importe, proveedor o condiciones por encima de la tolerancia; historial de versiones.</td><td>La recepción se valida contra la versión vigente.</td></tr><tr><td>CP-CMP-0056</td><td>RF-CMP-056; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Cerrar (saldo no se recibirá) o cancelar una OC con motivo, liberando el compromiso de fondos.</td><td><code>cmp.purchaseOrder.cancelled</code> libera el remanente en M14.</td></tr><tr><td>CP-CMP-0057</td><td>RF-CMP-057; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Rubros: &quot;Materiales eléctricos&quot; (pago diferido), &quot;Equipos de telecomunicaciones&quot;, &quot;Servicios&quot;</td><td>Publicar el compromiso de fondos al aprobar la OC (<code>cmp.purchaseOrder.approved</code>) con importe, moneda, fecha estimada de pago, servicio y centro de costo.</td><td>El informe distingue comprometido, devengado y pagado.</td></tr><tr><td>CP-CMP-0058</td><td>RF-CMP-058; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Al importar ítems de OC en remito o factura, copiar el motivo de compra a observaciones (P2647) y tomar el % de IVA del documento origen (P2690/P2791) o el del producto.</td><td>La alícuota tomada se muestra y puede corregirse con permiso.</td></tr><tr><td>CP-CMP-0059</td><td>RF-CMP-059; M12 §5.5; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Listar OC pendientes de aprobación, incluidas las de proveedores &quot;paga a otros&quot;.</td><td>La bandeja de aprobación muestra solo las de la banda del usuario.</td></tr></tbody></table><h3 id="_1-6-recepcion-y-remito-de-proveedor-m12-§5-6" tabindex="-1">1.6 Recepción y remito de proveedor (M12 §5.6) <a class="header-anchor" href="#_1-6-recepcion-y-remito-de-proveedor-m12-§5-6" aria-label="Permalink to &quot;1.6 Recepción y remito de proveedor (M12 §5.6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0060</td><td>RF-CMP-060; M12 §5.6; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Registrar la recepción (remito del proveedor) contra una o varias OC aprobadas, por cantidades parciales, con número del proveedor cuando el comprobante informa impuestos, depósito/destino, series y lotes (capturados en M13), receptor y…</td><td>CU-19: OC de 10, recepción de 6 → OC <code>partiallyReceived</code> con 4 pendientes.</td></tr><tr><td>CP-CMP-0061</td><td>RF-CMP-061; M12 §5.6; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>La recepción <strong>no mueve stock en M12</strong>: publica <code>cmp.receipt.confirmed</code> y M13 registra el ingreso físico; si M13 rechaza (depósito, serie), la recepción queda <code>stockPending</code> con alerta.</td><td>Ningún documento de M12 escribe movimientos de stock.</td></tr><tr><td>CP-CMP-0062</td><td>RF-CMP-062; M12 §5.6; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Conformidad de servicios sin recepción material (mantenimiento, honorarios): el responsable del servicio registra la conformidad total o parcial.</td><td>Una factura de servicio sin conformidad queda retenida.</td></tr><tr><td>CP-CMP-0063</td><td>RF-CMP-063; M12 §5.6; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Excesos de entrega: aceptar hasta la tolerancia configurada; por encima, rechazar o pedir aprobación.</td><td>Con tolerancia 0 %, recibir 11 de 10 exige aprobación.</td></tr><tr><td>CP-CMP-0064</td><td>RF-CMP-064; M12 §5.6; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Devoluciones al proveedor: remito de devolución que reabre o reduce el pendiente de la OC, solicita a M13 la salida y espera NC del proveedor.</td><td>La devolución queda vinculada a la NC cuando llega.</td></tr><tr><td>CP-CMP-0065</td><td>RF-CMP-065; M12 §5.6; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Opciones de carga: mostrar solo OC al importar ítems en remitos (P2649), no pedir depósito para productos sin stock (P2560), avisar si el producto no controla stock (P2989), cargar ítem &quot;pendiente&quot; (recibido sin ingreso) por defecto si…</td><td>Cada opción es configurable y se documenta en la ayuda.</td></tr><tr><td>CP-CMP-0066</td><td>RF-CMP-066; M12 §5.6; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>Cantidades con hasta los decimales de la unidad de medida del producto; la opción de 4 decimales para productos con stock (P2691) se reemplaza por la precisión de la unidad.</td><td>Una unidad &quot;unidad&quot; admite 0 decimales; &quot;metro&quot;, hasta 3.</td></tr><tr><td>CP-CMP-0067</td><td>RF-CMP-067; M12 §5.6; PRO-O3-03</td><td>O3</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Registro simplificado de ingreso de equipos serializados del piloto (OC opcional, proveedor del padrón mínimo, series).</td><td>OC-DEMO-002: 2 módems, series registradas en M13.</td></tr></tbody></table><h3 id="_1-7-comprobantes-de-proveedor-m12-§5-7" tabindex="-1">1.7 Comprobantes de proveedor (M12 §5.7) <a class="header-anchor" href="#_1-7-comprobantes-de-proveedor-m12-§5-7" aria-label="Permalink to &quot;1.7 Comprobantes de proveedor (M12 §5.7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0070</td><td>RF-CMP-070; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>Registrar facturas, ND, NC, tickets y recibos de proveedor: tipo, punto de venta, número, fecha, fecha contable, vencimiento(s), moneda/cotización, CAE/CAI, netos gravados por alícuota, no gravado, exento, IVA por alícuota, percepciones…</td><td>El total = gravado + no gravado + exento + IVA + percepciones + impuestos + otros.</td></tr><tr><td>CP-CMP-0071</td><td>RF-CMP-071; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Validaciones al registrar: proveedor, tipo, punto y número obligatorios; año razonable; período abierto de Compras, Stock y Contable; sin precios en cero; tipo permitido para la condición de IVA del proveedor (bloqueo o advertencia con…</td><td>Un comprobante duplicado devuelve <code>cmp/duplicate-invoice</code> con enlace al existente.</td></tr><tr><td>CP-CMP-0072</td><td>RF-CMP-072; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Diferencia admitida entre el total y la suma de componentes y entre cabecera e ítems: hasta P2057 (default ARS 0,50); controles de IVA de cabecera vs ítems y de cada ítem recalculado con su alícuota.</td><td>Una diferencia de ARS 0,60 con límite 0,50 impide registrar.</td></tr><tr><td>CP-CMP-0073</td><td>RF-CMP-073; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>integración</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Consultar CAE/CAI del comprobante en ARCA (M06) al cargar (P2977) y advertir si no existe.</td><td>Un CAE inexistente queda con advertencia visible.</td></tr><tr><td>CP-CMP-0074</td><td>RF-CMP-074; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Autocompletar fecha contable y vencimiento (P2388) con vencimiento por defecto (P2026 → días desde fecha); fecha contable en período abierto (P580 reemplazado por períodos).</td><td>La fecha contable propuesta pertenece a un período abierto.</td></tr><tr><td>CP-CMP-0075</td><td>RF-CMP-075; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Descuento global como ítem negativo del concepto configurado (P2403, obligatorio si se usan descuentos).</td><td>Sin concepto configurado, el descuento global no se habilita.</td></tr><tr><td>CP-CMP-0076</td><td>RF-CMP-076; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Recepciones: REC-DEMO-001 (6 medidores); REC-DEMO-002 (2 módems con series de prueba)</td><td>Importar ítems desde OC y/o recepciones (pendientes), y también facturar antes de recibir (factura anticipada: luego la recepción consume el pendiente de la factura, relación 5 → 4).</td><td>La factura anticipada queda retenida para pago hasta la recepción (§9.3).</td></tr><tr><td>CP-CMP-0077</td><td>RF-CMP-077; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Recepciones: REC-DEMO-001 (6 medidores); REC-DEMO-002 (2 módems con series de prueba)</td><td>Actualización del costo de compra del producto al registrar (salvo P264), preguntando antes si P426, usando el precio unitario neto del comprobante; registro del costo anterior. La valorización de stock es de M13 y <strong>no</strong> se reescribe el…</td><td>M13 recibe el costo facturado como ajuste de costo, no como reescritura del movimiento.</td></tr><tr><td>CP-CMP-0078</td><td>RF-CMP-078; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Registrar observación obligatoria al modificar un concepto en un comprobante (P2533) e historial de cambios.</td><td>La modificación muestra valor anterior y nuevo.</td></tr><tr><td>CP-CMP-0079</td><td>RF-CMP-079; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lookups: Destinatarios &quot;Depósito central&quot;, &quot;Taller&quot;; unidad de gasto &quot;Red eléctrica&quot;; combustibles &quot;Nafta&quot;, &quot;Gasoil&quot;; modalidades con umbrales ficticios</td><td>Imputación: servicio del cliente en el comprobante (P2277), obra por ítem (P3101), centros de costo y grupos de secciones (P2896) con % de IVA por sección (P2902) y reglas de asignación automática; IVA no tomado como gasto (P2890, efecto…</td><td>La distribución por centro de costo suma 100 % del neto.</td></tr><tr><td>CP-CMP-0080</td><td>RF-CMP-080; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Rubro de vivienda: si el comprobante es del rubro P2502, sus productos deben ser del rubro P2503.</td><td>Un producto de otro rubro se rechaza en ese comprobante.</td></tr><tr><td>CP-CMP-0081</td><td>RF-CMP-081; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Comprobantes en cuotas (vencimientos múltiples con periodicidad).</td><td>La suma de vencimientos = total.</td></tr><tr><td>CP-CMP-0082</td><td>RF-CMP-082; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Anticipos a proveedores sin factura (concepto P2035, sin rubro si P2017) y su posterior aplicación contra facturas; informar anticipos pendientes al pagar (P2777).</td><td>Un anticipo aplicado reduce el saldo de la factura y queda trazado.</td></tr><tr><td>CP-CMP-0083</td><td>RF-CMP-083; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Anular un comprobante: nunca se borra; se marca anulado con motivo si no tiene OP aplicada ni período cerrado; libera vínculos (recepción, portal, IA, combustible) y emite evento de reversión.</td><td>El comprobante anulado sigue consultable.</td></tr><tr><td>CP-CMP-0084</td><td>RF-CMP-084; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Opciones de carga e impresión: consultar si imprimir al registrar (P2424), separar comprobantes en libro IVA por defecto (P832, dato para M06), informe de libro IVA compras personalizado (P382, en M06), informe particularizado de…</td><td>P832 se guarda en el comprobante y M06 lo respeta.</td></tr><tr><td>CP-CMP-0085</td><td>RF-CMP-085; M12 §5.7; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Comprobantes de compra de energía y otros insumos regulados, disponibles para M03/M06 (balance energético, informes a reguladores).</td><td>El comprobante marcado &quot;compra de energía&quot; es consultable por M03. Detalle del circuito de energía y gas en RF-CMP-149…153 (HUE-ELE-01, HUE-GAS-04).</td></tr><tr><td>CP-CMP-0086</td><td>RF-CMP-086; M12 §5.7; PRO-O9-07</td><td>O9</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Integración con sueldos: comprobantes de proveedores-empleado y recibos pagados por OP (P2366) se informan a M16 sin que M12 genere novedades.</td><td>Con integración activa, M16 recibe el evento de pago.</td></tr></tbody></table><h3 id="_1-8-control-de-3-vias-y-habilitacion-de-pago-m12-§5-8" tabindex="-1">1.8 Control de 3 vías y habilitación de pago (M12 §5.8) <a class="header-anchor" href="#_1-8-control-de-3-vias-y-habilitacion-de-pago-m12-§5-8" aria-label="Permalink to &quot;1.8 Control de 3 vías y habilitación de pago (M12 §5.8)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0090</td><td>RF-CMP-090; M12 §5.8; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Conciliar automáticamente cada línea de factura con OC y recepción: cantidad facturada ≤ cantidad recibida (o conformada) + tolerancia; precio facturado = precio de OC ± tolerancia (porcentaje y monto); condiciones (moneda, plazo) iguales.</td><td>AGR-027: pedidos 10, recibidos 6, facturados 10 → excepción de cantidad por 4 y pago habilitado solo por 6 o bloqueado según política.</td></tr><tr><td>CP-CMP-0091</td><td>RF-CMP-091; M12 §5.8; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Crear una excepción por cada diferencia fuera de tolerancia con tipo (cantidad, precio, condición, sin OC, sin recepción), importe en disputa, causa y decisión (aceptar, reclamar NC, rechazar) aprobada por T11.</td><td>Ninguna factura con excepción abierta se incluye en una OP.</td></tr><tr><td>CP-CMP-0092</td><td>RF-CMP-092; M12 §5.8; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 con Rubros: &quot;Materiales eléctricos&quot; (pago diferido), &quot;Equipos de telecomunicaciones&quot;, &quot;Servicios&quot;</td><td>Habilitación de pago: automática si la factura concilia sin excepciones abiertas; manual con capability <code>cmp.pago.habilitar</code> y motivo en los demás casos. Reemplaza P2201/P2457 (&quot;pago autorizado / no autorizado / autorizar mayores a monto&quot;).</td><td>Habilitar sin permiso devuelve 403.</td></tr><tr><td>CP-CMP-0093</td><td>RF-CMP-093; M12 §5.8; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Compras sin OC: permitidas solo para categorías definidas (servicios públicos, impuestos, caja chica, gastos menores a un umbral), con aprobación posterior; informe de facturas sin OC.</td><td>Una factura sin OC fuera de las categorías crea excepción <code>withoutPO</code>.</td></tr><tr><td>CP-CMP-0094</td><td>RF-CMP-094; M12 §5.8; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Tablero de conciliación: facturas conciliadas, con excepción, retenidas, habilitadas; recepciones sin factura (pendientes de facturar) y facturas sin recepción.</td><td>El tablero cuadra con el saldo de proveedores a la fecha de corte.</td></tr></tbody></table><h3 id="_1-9-ordenes-de-pago-m12-§5-9" tabindex="-1">1.9 Órdenes de pago (M12 §5.9) <a class="header-anchor" href="#_1-9-ordenes-de-pago-m12-§5-9" aria-label="Permalink to &quot;1.9 Órdenes de pago (M12 §5.9)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0100</td><td>RF-CMP-100; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Preparar la OP: proveedor (o proveedor &quot;paga a otros&quot; con comprobantes de otros proveedores), selección de comprobantes habilitados con saldo (pago total o parcial), NC y anticipos a aplicar, anticipos nuevos sin factura, descuento, fecha…</td><td>El importe aplicado a una factura no supera su saldo.</td></tr><tr><td>CP-CMP-0101</td><td>RF-CMP-101; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Calcular las retenciones invocando el motor de M06 (<code>fis.service.calculateWithholdings</code>, antes <code>fis.withholding.calculate</code>) con proveedor, comprobantes, componentes, formalidad, anticipos y fecha; mostrar por régimen base, mínimo, escala…</td><td>CU-FIS-01: base 100.000, retención 2.000, neto 98.000.</td></tr><tr><td>CP-CMP-0102</td><td>RF-CMP-102; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Habilitación por régimen (P2037 IIBB, P2039 IVA, P2041 Ganancias, P2043 SUSS), no retener en comprobantes no formales (P410), IVA presunto en anticipos y comprobantes sin IVA discriminado (P2310), no retener en anticipos (P409), código de…</td><td>Con P2041 desactivado no se propone retención de Ganancias.</td></tr><tr><td>CP-CMP-0103</td><td>RF-CMP-103; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>seguridad</td><td>TEN-001 con Retención: RET-DEMO-001 por ARS 2.000 (M06)</td><td>Ajuste manual de una retención (P2836) solo con capability <code>cmp.retenciones.ajustar</code>, motivo y aprobación; queda el valor calculado y el ajustado.</td><td>Un ajuste sin motivo se rechaza.</td></tr><tr><td>CP-CMP-0104</td><td>RF-CMP-104; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 con SA: SA-DEMO-001 (10 medidores, aprobada); SA-DEMO-002 (concurso por ARS 3.000.000)</td><td>Aprobar la OP por bandas T11 y segregación; al aprobar: M06 confirma retenciones y numera certificados; M12 publica <code>cmp.paymentOrder.approved</code> con bruto, retenciones, neto, CBU validado y vencimiento para que M14 ejecute (medios, firmas…</td><td>Una OP no aprobada no aparece en la bandeja de M14.</td></tr><tr><td>CP-CMP-0105</td><td>RF-CMP-105; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Certificados de retención: imprimir/enviar automáticamente al aprobar por régimen (P2038, P2040, P2042, P2044), con punto de venta de IIBB (P2012) y fecha de información según día límite (P2045), generados por M06.</td><td>El certificado se envía al proveedor por mail/portal.</td></tr><tr><td>CP-CMP-0106</td><td>RF-CMP-106; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Al recibir <code>tes.paymentExecution.executed</code>, marcar la OP pagada, cancelar saldos y actualizar la cuenta corriente; con <code>tes.paymentExecution.voided</code> o anulación de la OP, reponer saldos, anular anticipos generados (si su contraparte no fue…</td><td>La anulación nunca borra registros; repone exactamente los saldos aplicados.</td></tr><tr><td>CP-CMP-0107</td><td>RF-CMP-107; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Rubros: &quot;Materiales eléctricos&quot; (pago diferido), &quot;Equipos de telecomunicaciones&quot;, &quot;Servicios&quot;</td><td>El saldo de la factura se reduce al aprobar la OP (comprometido para pago) y se considera cancelado al ejecutarse; no se pisa el vencimiento original.</td><td>El informe de antigüedad usa el vencimiento original.</td></tr><tr><td>CP-CMP-0108</td><td>RF-CMP-108; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Opciones de OP: imprimir al emitir (P2018), mostrar asiento contable propuesto (P2308, desde M15), permitir modificar la fecha de la OP (P2572), pagar facturas con fecha contable posterior al pago (P110), plantilla para envío masivo de OP…</td><td>El envío masivo usa la plantilla configurada.</td></tr><tr><td>CP-CMP-0109</td><td>RF-CMP-109; M12 §5.9; PRO-O9-07</td><td>O9</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Adelantos de sueldo a empleados (concepto P2034, tipo de novedad P2538) no se gestionan como OP de compras: se derivan a M16.</td><td>Una OP a un proveedor-empleado con concepto de adelanto se rechaza con enlace a M16.</td></tr><tr><td>CP-CMP-0110</td><td>RF-CMP-110; M12 §5.9; PRO-O9-07</td><td>O9</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Pagos de recibos de sueldo mediante OP solo si M16 lo solicita (lote aprobado); M12 no borra facturas de sueldo al anular.</td><td>La anulación avisa a M16 en lugar de borrar.</td></tr><tr><td>CP-CMP-0111</td><td>RF-CMP-111; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Consultar pagos pendientes de salida (efectivo pendiente de caja), pagos diferidos y estado de ejecución informado por M14.</td><td>El informe se abre por medio con fila de total.</td></tr><tr><td>CP-CMP-0112</td><td>RF-CMP-112; M12 §5.9; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Portal de proveedores: el proveedor ve OC, estado de sus comprobantes (pendiente, registrado, rechazado con motivo, habilitado, en pago, pagado) y descarga certificados de retención y comprobantes de pago.</td><td>Los estados se derivan de §8, sin la ambigüedad del estado &quot;A&quot;.</td></tr></tbody></table><h3 id="_1-10-importacion-de-mis-comprobantes-portal-e-ia-m12-§5-10" tabindex="-1">1.10 Importación de Mis Comprobantes, portal e IA (M12 §5.10) <a class="header-anchor" href="#_1-10-importacion-de-mis-comprobantes-portal-e-ia-m12-§5-10" aria-label="Permalink to &quot;1.10 Importación de Mis Comprobantes, portal e IA (M12 §5.10)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0120</td><td>RF-CMP-120; M12 §5.10; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>integración</td><td>TEN-001 con Mis Comprobantes: REG-DEMO: 5 comprobantes recibidos no registrados (lote ficticio)</td><td>Recibir de M06 los comprobantes recibidos que figuran en Mis Comprobantes de ARCA y no están registrados en M12, y crear <strong>borradores</strong> de comprobante de proveedor (proveedor por CUIT, tipo, punto, número, fecha, importes por alícuota)…</td><td>Un comprobante importado nunca queda registrado sin confirmación humana.</td></tr><tr><td>CP-CMP-0121</td><td>RF-CMP-121; M12 §5.10; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Informe de diferencias entre compras registradas y Mis Comprobantes (faltantes, sobrantes, importes distintos), con acceso al borrador o al registrado.</td><td>El informe cuadra con la conciliación de M06 del mismo período.</td></tr><tr><td>CP-CMP-0122</td><td>RF-CMP-122; M12 §5.10; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Recibir comprobantes cargados por el proveedor en el portal (datos + PDF), rechazar duplicados (CUIT + tipo + punto + número), revisar y registrar o rechazar con motivo.</td><td>El proveedor ve el motivo del rechazo.</td></tr><tr><td>CP-CMP-0130</td><td>RF-CMP-130; M12 §5.10; PRO-O11-05</td><td>O11</td><td>Estándar</td><td>regla</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Lectura de facturas de proveedor (PDF/imagen) con IA: extrae cabecera, importes y alícuotas, distingue a la cooperativa (CUIT y razón social del tenant, P518/P519) del emisor, propone proveedor, ítems e imputación; una persona revisa…</td><td>La propuesta muestra la confianza por campo; nada se registra sin confirmación.</td></tr><tr><td>CP-CMP-0131</td><td>RF-CMP-131; M12 §5.10; PRO-O11-05</td><td>O11</td><td>Estándar</td><td>seguridad</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Auditoría de cada uso de IA (tipo, documento, modelo, tokens, usuario, resultado aceptado/corregido) sin guardar datos personales innecesarios; activación por tenant con acuerdo de tratamiento de datos. La auditoría por persona es…</td><td>El tenant ve el consumo y la tasa de corrección.</td></tr></tbody></table><h3 id="_1-11-informes-y-transversales-m12-§5-11" tabindex="-1">1.11 Informes y transversales (M12 §5.11) <a class="header-anchor" href="#_1-11-informes-y-transversales-m12-§5-11" aria-label="Permalink to &quot;1.11 Informes y transversales (M12 §5.11)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0140</td><td>RF-CMP-140; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Informes de compras (sección 15): SA por estado y aprobación, cotizaciones y comparativos, OC pendientes de recepción, recepciones pendientes de facturar, facturas sin OC, diferencias de comprobantes, cuenta corriente y antigüedad de…</td><td>Cada informe declara fórmula, universo y fecha de corte.</td></tr><tr><td>CP-CMP-0141</td><td>RF-CMP-141; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Trazabilidad documento a documento por ítem (origen y destino con cantidades y precios) en todos los documentos, no solo en el primer ítem.</td><td>Cada línea muestra SA, cotización, OC, recepción y factura vinculadas.</td></tr><tr><td>CP-CMP-0142</td><td>RF-CMP-142; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Respetar el cierre de períodos de Compras (P500), Stock y Contable mediante la entidad unificada de períodos (T04/M15).</td><td>Un comprobante con fecha contable en período cerrado se rechaza.</td></tr><tr><td>CP-CMP-0143</td><td>RF-CMP-143; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>migración</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Identificadores internos por documento (ObjectId) y numeración legible por tipo y punto; los ID compuestos de ProCoop se conservan como referencia de migración.</td><td>No se usan claves concatenadas como identidad.</td></tr><tr><td>CP-CMP-0144</td><td>RF-CMP-144; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Retención: RET-DEMO-001 por ARS 2.000 (M06)</td><td>Integrar el efecto contable en línea (DEC-009): cada comprobante, recepción con pendiente, retención y OP publica su evento con imputación para M15; cuenta de compras por defecto del proveedor (P2112) y cuenta de productos pendientes de…</td><td>Anular un comprobante genera la reversión contable vinculada.</td></tr><tr><td>CP-CMP-0145</td><td>RF-CMP-145; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 con Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</td><td>Etiquetas por diccionario, plantillas por tenant, auditoría de todo cambio, aislamiento por tenant en consultas, exportaciones, portal y APIs.</td><td>Un proveedor del portal de TEN-001 no ve datos de TEN-002 aunque tenga el mismo CUIT.</td></tr><tr><td>CP-CMP-0146</td><td>RF-CMP-146; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: &quot;Flete&quot;, &quot;Mantenimiento&quot;, &quot;Servicios públicos&quot;, &quot;Anticipo a proveedores&quot;</td><td>Copiar entre tenants la configuración de M12 (conceptos, modalidades, políticas, plantillas), sin proveedores ni operaciones.</td><td>La copia no incluye datos de terceros.</td></tr><tr><td>CP-CMP-0147</td><td>RF-CMP-147; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tenant: TEN-001 &quot;Cooperativa Demo&quot;</td><td>Integración con fabricación: las opciones de partes de producción (P2967, P3043, P3057, P3171) pertenecen a M13; M12 solo recibe SA de fabricación.</td><td>M12 no ofrece opciones de partes de producción; las SA de fabricación recibidas desde M13 se procesan como cualquier SA con su origen identificado.</td></tr><tr><td>CP-CMP-0148</td><td>RF-CMP-148; M12 §5.11; PRO-O8-03</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Rubros: &quot;Materiales eléctricos&quot; (pago diferido), &quot;Equipos de telecomunicaciones&quot;, &quot;Servicios&quot;</td><td>Parámetros de caja de pagos y medios (P134, P135, P144, P146, P402, P2000–P2004, P2015, P2016, P2025, P2065, P2079, P2433, P2573, P3044, P2952) pertenecen a M14; M12 los respeta al preparar la OP (por ejemplo, pago diferido solo a rubros…</td><td>La OP propone medios compatibles con la configuración de M14.</td></tr></tbody></table><h3 id="_1-12-abastecimiento-mayorista-y-derechos-de-senales-m12-§5-12" tabindex="-1">1.12 Abastecimiento mayorista y derechos de señales (M12 §5.12) <a class="header-anchor" href="#_1-12-abastecimiento-mayorista-y-derechos-de-senales-m12-§5-12" aria-label="Permalink to &quot;1.12 Abastecimiento mayorista y derechos de señales (M12 §5.12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CMP-0149</td><td>RF-CMP-149; M12 §5.12; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;…</td><td>Recibir la factura mensual del mayorista de energía (EPEC u otro mayorista configurado) por archivo (FI-INT-33) o carga manual, como comprobante de proveedor con <code>wholesaleSupply.kind = energy</code> y detalle por punto de compra o frontera…</td><td>Importar dos veces el mismo archivo no duplica el comprobante (idempotencia por proveedor + tipo + punto de venta + número); cada renglón queda vinculado a un <code>meteringPointId</code> de M03 o falla con <code>cmp/supply-point-unknown</code>.</td></tr><tr><td>CP-CMP-0150</td><td>RF-CMP-150; M12 §5.12; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Controlar cada renglón de la factura mayorista contra la medición propia del mismo punto y período de M03 (puntos <code>purchase</code>/<code>boundary</code>, RF-MED-012, RF-MED-100), obtenida con API-MED-78 <code>GET /api/admin/med/purchase-volumes</code> (RF-MED-129)…</td><td>Con tolerancia 1 %, factura de 100.000 kWh y medición propia de 98.000 kWh, se crea la excepción por 2.000 kWh y el comprobante queda <code>paymentRelease = blocked</code>; sin medición propia del período, la excepción es <code>meteringMissing</code>.</td></tr><tr><td>CP-CMP-0151</td><td>RF-CMP-151; RN-TAR-227; M12 §5.12; PRO-O8-02</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</td><td>Balance mensual comprado contra facturado por servicio y zona: cantidad comprada (facturas mayoristas aprobadas), cantidad medida en frontera (M03, API-MED-78 / RF-MED-129), cantidad facturada a usuarios del mismo período (consumos…</td><td>Comprado 100.000 kWh y facturado 91.000 kWh → pérdida 9.000 kWh (9 %); el balance usa la misma fecha de corte que el informe de pérdidas de M03 y no modifica tarifas (RN-TAR-227).</td></tr><tr><td>CP-CMP-0152</td><td>RF-CMP-152; RN-TAR-035; M12 §5.12; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Recibir la factura de la distribuidora de gas (archivo FI-INT-115 de T06 o carga manual) con <code>wholesaleSupply.kind = gas</code>: m³ por punto de compra, poder calorífico o factor de corrección informado, cargos fijos, transporte y tributos…</td><td>Una factura de gas con factor de corrección distinto del vigente en M04 genera excepción <code>meteringMismatch</code> aunque los m³ sin corregir coincidan con los de M03.</td></tr><tr><td>CP-CMP-0153</td><td>RF-CMP-153; RN-CON-069; M12 §5.12; PRO-O8-02</td><td>O8</td><td>Núcleo</td><td>regla</td><td>TEN-001 con OC: OC-001 (BASE §19: 10 medidores × ARS 20.000, 6 recibidos); OC-DEMO-002 (BASE §78: 2 módems × ARS 20.000, servicio INT)</td><td>Publicar el registro del comprobante mayorista (EVT-CMP-08) con <code>supplyKind</code> y rol de costo de abastecimiento para que M15 registre el costo por servicio (RN-CON-069); nunca se genera un cargo o recargo al usuario desde M12.</td><td>El asiento de una factura mayorista imputa costo de abastecimiento del servicio ELE o GAS; anular el comprobante genera la reversión vinculada.</td></tr><tr><td>CP-CMP-0154</td><td>RF-CMP-154; M12 §5.12; PRO-O10-09</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 con OC: OC-001 (BASE §19: 10 medidores × ARS 20.000, 6 recibidos); OC-DEMO-002 (BASE §78: 2 módems × ARS 20.000, servicio INT)</td><td>Contratos de derechos de señales de TV por programadora: señales o paquetes alcanzados, precio por abonado activo, mínimo garantizado, moneda, vigencia y base de cómputo (PRM-CMP-115).</td><td>No se puede liquidar un período sin contrato vigente para la programadora.</td></tr><tr><td>CP-CMP-0155</td><td>RF-CMP-155; M12 §5.12; PRO-O10-09</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</td><td>Liquidación mensual de derechos de señales (JOB-CMP-09): por programadora y paquete, cantidad de abonados activos según el informe de abonados activos por paquete de M02 a la fecha de corte (RF-CAT-116, API-CAT-56 `GET…</td><td>Con 1.200 abonados del paquete básico a ARS 150 y mínimo ARS 150.000, la liquidación es ARS 180.000; con 800 abonados es ARS 150.000 (mínimo). Una factura por 1.250 abonados genera excepción de cantidad por 50.</td></tr></tbody></table><h2 id="_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" tabindex="-1">2. Casos por escenario y criterio de aceptación con ID <a class="header-anchor" href="#_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" aria-label="Permalink to &quot;2. Casos por escenario y criterio de aceptación con ID&quot;">​</a></h2><p><strong>CP-CMP-5001 — ESC-CMP-01. CU-19 recepción parcial</strong></p><ul><li>Cubre: ESC-CMP-01; relacionados: CU-19; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando CU-19 recepción parcial</li><li>Entonces OC con 4 pendientes; no <code>received</code>.</li></ul><p><strong>CP-CMP-5002 — ESC-CMP-02. AGR-027 10/6/10</strong></p><ul><li>Cubre: ESC-CMP-02; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando AGR-027 10/6/10</li><li>Entonces Excepción; no se paga como recibido todo.</li></ul><p><strong>CP-CMP-5003 — ESC-CMP-03. Precio facturado 5 % mayor, tolerancia 2 %</strong></p><ul><li>Cubre: ESC-CMP-03; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Precio facturado 5 % mayor, tolerancia 2 %</li><li>Entonces Excepción de precio.</li></ul><p><strong>CP-CMP-5004 — ESC-CMP-04. Diferencia de total ARS 0,60 con límite 0,50</strong></p><ul><li>Cubre: ESC-CMP-04; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Diferencia de total ARS 0,60 con límite 0,50</li><li>Entonces No se registra (<code>cmp/total-mismatch</code>).</li></ul><p><strong>CP-CMP-5005 — ESC-CMP-05. Comprobante duplicado</strong></p><ul><li>Cubre: ESC-CMP-05; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Comprobante duplicado</li><li>Entonces <code>cmp/duplicate-invoice</code>.</li></ul><p><strong>CP-CMP-5006 — ESC-CMP-06. Procesar ítem de SA no aprobada (defecto ProCoop)</strong></p><ul><li>Cubre: ESC-CMP-06; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: migración</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: SA: SA-DEMO-001 (10 medidores, aprobada); SA-DEMO-002 (concurso por ARS 3.000.000)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Procesar ítem de SA no aprobada (defecto ProCoop)</li><li>Entonces <code>cmp/request-not-approved</code>.</li></ul><p><strong>CP-CMP-5007 — ESC-CMP-07. SA de hace 45 días con vigencia 30</strong></p><ul><li>Cubre: ESC-CMP-07; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando SA de hace 45 días con vigencia 30</li><li>Entonces No aparece en pendientes.</li></ul><p><strong>CP-CMP-5008 — ESC-CMP-08. Aprobación masiva de OC sin banda suficiente</strong></p><ul><li>Cubre: ESC-CMP-08; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Aprobación masiva de OC sin banda suficiente</li><li>Entonces Rechazo por documento con causa.</li></ul><p><strong>CP-CMP-5009 — ESC-CMP-09. Factura de servicio sin conformidad</strong></p><ul><li>Cubre: ESC-CMP-09; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: OC: OC-001 (BASE §19: 10 medidores × ARS 20.000, 6 recibidos); OC-DEMO-002 (BASE §78: 2 módems × ARS 20.000, servicio INT)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Factura de servicio sin conformidad</li><li>Entonces <code>onHold</code>.</li></ul><p><strong>CP-CMP-5010 — ESC-CMP-10. Factura sin OC de categoría no permitida</strong></p><ul><li>Cubre: ESC-CMP-10; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;; PROV-DEMO-003 &quot;Equipos de Red Demo SA&quot; (módems); PROV-DEMO-004 &quot;Servicios…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Factura sin OC de categoría no permitida</li><li>Entonces Excepción <code>withoutPO</code>.</li></ul><p><strong>CP-CMP-5011 — ESC-CMP-11. CU-FIS-01</strong></p><ul><li>Cubre: ESC-CMP-11; relacionados: CU-FIS-01; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Retención: RET-DEMO-001 por ARS 2.000 (M06)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando CU-FIS-01</li><li>Entonces Retención 2.000, neto 98.000, factura cancelada por 100.000.</li></ul><p><strong>CP-CMP-5012 — ESC-CMP-12. Anulación de OP ejecutada</strong></p><ul><li>Cubre: ESC-CMP-12; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Anulación de OP ejecutada</li><li>Entonces Exige anular primero en M14; luego repone saldos y anula retenciones conservando importes.</li></ul><p><strong>CP-CMP-5013 — ESC-CMP-13. OP con transferencia a CBU pendiente de aprobación</strong></p><ul><li>Cubre: ESC-CMP-13; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: CBU: Un CBU aprobado por PROV-DEMO-001 y uno pendiente de aprobación por PROV-DEMO-002 (números sintéticos que no validan contra un banco real)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando OP con transferencia a CBU pendiente de aprobación</li><li>Entonces <code>cmp/bank-account-not-approved</code>.</li></ul><p><strong>CP-CMP-5014 — ESC-CMP-14. Deshacer vínculo con cantidad 2,5</strong></p><ul><li>Cubre: ESC-CMP-14; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Deshacer vínculo con cantidad 2,5</li><li>Entonces Repone 2,5 (no 2).</li></ul><p><strong>CP-CMP-5015 — ESC-CMP-15. Compra compartida 50/50 INT/TV por ARS 40.000</strong></p><ul><li>Cubre: ESC-CMP-15; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: OC: OC-001 (BASE §19: 10 medidores × ARS 20.000, 6 recibidos); OC-DEMO-002 (BASE §78: 2 módems × ARS 20.000, servicio INT)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Compra compartida 50/50 INT/TV por ARS 40.000</li><li>Entonces Informe por servicio 20.000 + 20.000; total 40.000.</li></ul><p><strong>CP-CMP-5016 — ESC-CMP-16. Borrador desde Mis Comprobantes sin revisión</strong></p><ul><li>Cubre: ESC-CMP-16; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Borrador desde Mis Comprobantes sin revisión</li><li>Entonces No impacta libro IVA ni cuenta corriente.</li></ul><p><strong>CP-CMP-5017 — ESC-CMP-17. Proveedor del portal de TEN-001 consulta OC de TEN-002 con mismo CUIT</strong></p><ul><li>Cubre: ESC-CMP-17; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de M12 §18.</li><li>Datos de prueba: Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Proveedor del portal de TEN-001 consulta OC de TEN-002 con mismo CUIT</li><li>Entonces 404.</li></ul><p><strong>CP-CMP-5018 — ESC-CMP-18. Recepción rechazada por M13 (serie duplicada)</strong></p><ul><li>Cubre: ESC-CMP-18; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Recepción rechazada por M13 (serie duplicada)</li><li>Entonces <code>stockStatus = rejected</code> y alerta; la OC no se da por recibida.</li></ul><p><strong>CP-CMP-5019 — ESC-CMP-19. Pagar factura: vencimiento original</strong></p><ul><li>Cubre: ESC-CMP-19; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Pagar factura: vencimiento original</li><li>Entonces El informe de antigüedad conserva el vencimiento original.</li></ul><p><strong>CP-CMP-5020 — ESC-CMP-20. Adelanto de sueldo desde OP</strong></p><ul><li>Cubre: ESC-CMP-20; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Adelanto de sueldo desde OP</li><li>Entonces Rechazo con derivación a M16.</li></ul><p><strong>CP-CMP-5021 — ESC-CMP-21. Factura mayorista de energía ficticia por 100.000 kWh en el punto de frontera FR-DEMO-01; M03 midió 98.000 kWh; tolerancia 1 % (HUE-ELE-01)</strong></p><ul><li>Cubre: ESC-CMP-21; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Factura mayorista de energía ficticia por 100.000 kWh en el punto de frontera FR-DEMO-01; M03 midió 98.000 kWh; tolerancia 1 % (HUE-ELE-01)</li><li>Entonces Excepción <code>meteringMismatch</code> por 2.000 kWh; <code>paymentRelease = blocked</code> hasta la decisión.</li></ul><p><strong>CP-CMP-5022 — ESC-CMP-22. Factura de gas de la distribuidora sin medición propia del período en M03 (HUE-GAS-04)</strong></p><ul><li>Cubre: ESC-CMP-22; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Factura de gas de la distribuidora sin medición propia del período en M03 (HUE-GAS-04)</li><li>Entonces Excepción <code>meteringMissing</code>; JOB-CMP-10 la reevalúa al llegar la medición.</li></ul><p><strong>CP-CMP-5023 — ESC-CMP-23. Balance del período: comprado 100.000 kWh, facturado a usuarios 91.000 kWh (HUE-ELE-01)</strong></p><ul><li>Cubre: ESC-CMP-23; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Balance del período: comprado 100.000 kWh, facturado a usuarios 91.000 kWh (HUE-ELE-01)</li><li>Entonces Pérdida 9.000 kWh (9 %); al aprobar se publica EVT-CMP-16; ningún usuario recibe recargo.</li></ul><p><strong>CP-CMP-5024 — ESC-CMP-24. Programadora PROG-DEMO-01, paquete básico a ARS 150 por abonado, mínimo ARS 150.000; M02 informa 1.200 abonados activos (HUE-TV-01)</strong></p><ul><li>Cubre: ESC-CMP-24; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Tenant: TEN-001 &quot;Cooperativa Demo&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Programadora PROG-DEMO-01, paquete básico a ARS 150 por abonado, mínimo ARS 150.000; M02 informa 1.200 abonados activos (HUE-TV-01)</li><li>Entonces Liquidación ARS 180.000; al aprobar se publica EVT-CMP-17 y M15 devenga el costo.</li></ul><p><strong>CP-CMP-5025 — ESC-CMP-25. Reejecutar JOB-CMP-09 del mismo período con la liquidación ya aprobada (HUE-TV-01)</strong></p><ul><li>Cubre: ESC-CMP-25; M12 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: SA: SA-DEMO-001 (10 medidores, aprobada); SA-DEMO-002 (concurso por ARS 3.000.000)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Reejecutar JOB-CMP-09 del mismo período con la liquidación ya aprobada (HUE-TV-01)</li><li>Entonces No se crea otra liquidación; una corrección se registra como ajuste del período siguiente.</li></ul><h2 id="_3-casos-por-caso-de-uso-cu" tabindex="-1">3. Casos por caso de uso (CU) <a class="header-anchor" href="#_3-casos-por-caso-de-uso-cu" aria-label="Permalink to &quot;3. Casos por caso de uso (CU)&quot;">​</a></h2><p><strong>CP-CMP-8001 — CU-19. Compra con entrega parcial (BASE §19)</strong></p><ul><li>Cubre: CU-19; M12 §16</li><li>Ola: O8 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado TEN-001; proveedor PROV-DEMO-002; producto &quot;Medidor monofásico&quot;. -; actor: depósito (solicitante), comprador, aprobador, receptor, cuentas a pagar. -, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando SA de 10 medidores → aprobación → cotizaciones y comparación → OC-001 por 10 × ARS 20.000 = ARS 200.000 (aprobada por banda) → recepción de 6 → OC con 4 pendientes (no se da por entregado todo). - Excepción: la factura llega por 10 o con precio ARS 21.000: excepción de cantidad (4 unidades) o de precio (5 % &gt; tolerancia 2 %); la factura queda retenida antes de autorizar el pago. -</li><li>Entonces Compra de ARS 200.000 base; 6 recibidas, 4 pendientes; pago solo de lo conciliado o tras decisión.</li></ul><p><strong>CP-CMP-8002 — CU-OPE-01. Compra de módems por servicio (BASE §78)</strong></p><ul><li>Cubre: CU-OPE-01; RN-VEN-006; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: OC: OC-001 (BASE §19: 10 medidores × ARS 20.000, 6 recibidos); OC-DEMO-002 (BASE §78: 2 módems × ARS 20.000, servicio INT)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando OC-DEMO-002 por 2 módems a ARS 20.000 (total ARS 40.000) con servicio INT en la línea → recepción con series (M13) → un módem se asigna a instalador y se aplica a una OT, el otro queda disponible (M13) → factura y OP siguen cuentas a pagar y tesorería. - Control: el costo del módem no se transforma en cargo al socio (M11 RN-VEN-006); la existencia no se reduce dos veces.</li><li>Entonces Se completa «Compra de módems por servicio (BASE §78)» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-CMP-8003 — CU-FIS-01. Pago con retención (BASE §61, compartido con M06/M14)</strong></p><ul><li>Cubre: CU-FIS-01; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: integración</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;; PROV-DEMO-003 &quot;Equipos de Red Demo SA&quot; (módems); PROV-DEMO-004 &quot;Servicios…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando OP a PROV-DEMO-001 por factura de ARS 100.000 → M06 determina RET-DEMO-001 por ARS 2.000 → neto ARS 98.000 → aprobación → M14 paga 98.000 → la factura queda cancelada por 100.000; M06 genera certificado y obligación. - Control: un reintento no genera otra retención; exportar no es presentar.</li><li>Entonces Se completa «Pago con retención (BASE §61, compartido con M06/M14)» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-CMP-8004 — CU-CMP-01. Control de 3 vías con excepción (AGR-027)</strong></p><ul><li>Cubre: CU-CMP-01; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Comprobantes: FC-DEMO-001 por 10 medidores (genera excepción de cantidad); FC-DEMO-002 de PROV-DEMO-001 por ARS 100.000</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando pedidos 10, recibidos 6, facturados 10 → excepción de cantidad por 4 → el autorizador elige &quot;reclamar NC&quot; → se habilitan ARS 120.000 → llega NC por ARS 80.000 → excepción resuelta. -</li><li>Entonces El pago respeta lo autorizado y el stock representa lo recibido.</li></ul><p><strong>CP-CMP-8005 — CU-CMP-02. Factura recibida por el portal</strong></p><ul><li>Cubre: CU-CMP-02; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando el proveedor invitado sube su factura con PDF → duplicado rechazado si ya existe → cuentas a pagar registra (importando la OC) → el proveedor ve &quot;Registrado&quot;, luego &quot;Habilitado&quot;, &quot;En pago&quot; y &quot;Pagado&quot; y descarga el certificado de retención.</li><li>Entonces Se completa «Factura recibida por el portal» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-CMP-8006 — CU-CMP-03. Importación desde Mis Comprobantes</strong></p><ul><li>Cubre: CU-CMP-03; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Mis Comprobantes: REG-DEMO: 5 comprobantes recibidos no registrados (lote ficticio)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando M06 concilia el período y detecta 5 comprobantes recibidos no registrados → se crean 5 borradores → el administrativo completa imputación de 4 y descarta 1 (no corresponde) con motivo → la conciliación de M06 se actualiza.</li><li>Entonces Se completa «Importación desde Mis Comprobantes» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-CMP-8007 — CU-CMP-04. Lectura de factura con IA</strong></p><ul><li>Cubre: CU-CMP-04; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando el usuario sube un PDF → la IA propone proveedor (por CUIT del emisor, distinto del de la cooperativa), importes y alícuotas con confianza → el usuario corrige una alícuota y registra → la auditoría registra la corrección.</li><li>Entonces Se completa «Lectura de factura con IA» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-CMP-8008 — CU-CMP-05. Concurso de precios</strong></p><ul><li>Cubre: CU-CMP-05; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Proveedores: PROV-DEMO-001 &quot;Proveedor Demo Retención SA&quot; (responsable inscripto, régimen de retención asignado en M06); PROV-DEMO-002 &quot;Medidores Demo SRL&quot;; PROV-DEMO-003 &quot;Equipos de Red Demo SA&quot; (módems); PROV-DEMO-004 &quot;Servicios…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando SA de ARS 3.000.000 supera el umbral de concurso → se publica el evento e invita a 4 proveedores → ofertas en sobre cerrado → apertura con acta → planilla de adjudicación → OC al adjudicado.</li><li>Entonces Se completa «Concurso de precios» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-CMP-8009 — CU-CMP-06. Alta de CBU con aprobación</strong></p><ul><li>Cubre: CU-CMP-06; M12 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M12 §18.</li><li>Datos de prueba: Portal: Usuario invitado &quot;proveedor.demo&quot; de PROV-DEMO-003 (rol <code>supplier</code>)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando el proveedor solicita en el portal cambiar su CBU → el comprador lo carga → otro usuario aprueba tras verificación telefónica → la próxima OP usa el nuevo CBU; antes de aprobarse, la OP usa el anterior o queda sin transferencia.</li><li>Entonces Se completa «Alta de CBU con aprobación» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul>',100)])])}const m=o(i,[["render",r]]);export{P as __pageData,m as default};
